sys_script_include.script:
var CarePlanService = Class.create();

CarePlanService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Care Plan record exists.
     *
     * @param {String} carePlanSysId
     * @return {Boolean}
     */
    carePlanExists: function(carePlanSysId) {

        if (this.validationUtils.isEmpty(carePlanSysId)) {
            return false;
        }

        var carePlan = new GlideRecord('x_2130921_caresy_0_care_plan');

        if (!carePlan.isValid()) {
            gs.error('CarePlanService: Care Plan table is invalid.');
            return false;
        }

        return carePlan.get(carePlanSysId);
    },

    /**
     * Retrieve a Care Plan record.
     *
     * @param {String} carePlanSysId
     * @return {GlideRecord|null}
     */
    getCarePlan: function(carePlanSysId) {

        if (this.validationUtils.isEmpty(carePlanSysId)) {
            return null;
        }

        var carePlan = new GlideRecord('x_2130921_caresy_0_care_plan');

        if (!carePlan.isValid()) {
            gs.error('CarePlanService: Care Plan table is invalid.');
            return null;
        }

        if (carePlan.get(carePlanSysId)) {
            return carePlan;
        }

        return null;
    },

    /**
     * Check whether a Care Plan is active.
     *
     * @param {String} carePlanSysId
     * @return {Boolean}
     */
    isCarePlanActive: function(carePlanSysId) {

        var carePlan = this.getCarePlan(carePlanSysId);

        if (!carePlan) {
            return false;
        }

        return carePlan.getValue('active') == 'true';
    },

    type: 'CarePlanService'
};
